AggregationStrategy merge = AggregationStrategies.beanAllowNull(new OrderMerger(), "merge");

from("jms:orders")
    .enrich("http:customers/orders/${header.orderId}", merge)   // resource exchange
    .to("jms:enriched-orders");
// file/FTP resource: .pollEnrich("file:inbox?fileName=data.txt", 10000, merge)

Function<Order, Order> enrich = order -> {
    Customer c = cache.computeIfAbsent(order.customerId(),
        id -> customers.find(id).orElse(Customer.unknown(id)));   // cache-aside
    return order.withCustomer(c.name(), c.region());
};
